        # Plan-mode hard write gate: block mutates_state tools when the active
        # profile is PLAN. Carve-outs:
        #  1. Tools in _PLAN_GATE_BYPASS_TOOLS (bash) bypass when their
        #     resolve_permission returns ALWAYS — the PLAN profile narrows bash
        #     to a read-only command allowlist, so ALWAYS means "PLAN permits".
        #  2. `task` may dispatch a SAFE (read-only) subagent (e.g. explore);
        #     that subagent cannot violate the plan invariant by construction.
        # write_file/search_replace are intentionally NOT listed: v2.13's PLAN
        # _plan_overrides already narrows them to the plan-file path via the
        # permission layer. MCP and non-SAFE task targets stay blocked.
        # The substring "[Plan mode: write operations disabled]" is contract.
        if (
            self.agent_manager.active_profile.name == BuiltinAgentName.PLAN
            and tool_instance.__class__.mutates_state
        ):
            allowlisted = False
            if tool_call.tool_name in _PLAN_GATE_BYPASS_TOOLS:
                permission_ctx: PermissionContext | None = None
                try:
                    permission_ctx = tool_instance.resolve_permission(
                        tool_call.validated_args
                    )
                except Exception:
                    permission_ctx = None
                allowlisted = (
                    permission_ctx is not None
                    and permission_ctx.permission == ToolPermission.ALWAYS
                )
            elif tool_call.tool_name == "task":
                target_agent_name = getattr(tool_call.validated_args, "agent", None)
                if target_agent_name:
                    try:
                        target_profile = self.agent_manager.get_agent(
                            target_agent_name
                        )
                    except Exception:
                        target_profile = None
                    allowlisted = (
                        target_profile is not None
                        and target_profile.safety == AgentSafety.SAFE
                    )
            if not allowlisted:
                yield self._tool_failure_event(
                    tool_call,
                    f"<{TOOL_ERROR_TAG}>[Plan mode: write operations disabled]</{TOOL_ERROR_TAG}>",
